CREATE TABLE IF NOT EXISTS richo_policy_versions(id uuid PRIMARY KEY,name text NOT NULL,version text NOT NULL,scope text NOT NULL,environment text NOT NULL DEFAULT '*',priority integer NOT NULL DEFAULT 100,effect text NOT NULL CHECK(effect IN('allow','deny','require_approval')),conditions jsonb NOT NULL DEFAULT '{}'::jsonb,requires_approvals jsonb NOT NULL DEFAULT '[]'::jsonb,separation_of_duties jsonb NOT NULL DEFAULT '[]'::jsonb,parent_policy_id uuid REFERENCES richo_policy_versions(id),effective_from timestamptz NOT NULL,effective_to timestamptz,status text NOT NULL DEFAULT 'active',metadata jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(name,version,environment));
CREATE TABLE IF NOT EXISTS richo_policy_delegations(id uuid PRIMARY KEY,principal text NOT NULL,capabilities jsonb NOT NULL,scope text NOT NULL,environment text NOT NULL DEFAULT '*',expires_at timestamptz NOT NULL,granted_by text NOT NULL,reason text,status text NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS richo_policy_decisions(id uuid PRIMARY KEY,decision text NOT NULL,reason text NOT NULL,policy_id uuid,policy_version text,request jsonb NOT NULL,matched_policy_ids jsonb NOT NULL DEFAULT '[]'::jsonb,conflicts jsonb NOT NULL DEFAULT '[]'::jsonb,delegation_ids jsonb NOT NULL DEFAULT '[]'::jsonb,separation_of_duties jsonb NOT NULL DEFAULT '{}'::jsonb,approval_chain jsonb NOT NULL DEFAULT '[]'::jsonb,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS richo_policy_scope_idx ON richo_policy_versions(scope,environment,status,priority);
CREATE INDEX IF NOT EXISTS richo_policy_delegation_principal_idx ON richo_policy_delegations(principal,status,expires_at);
